// espera crescente: 1s, 2s, 4s — e desiste
async function chamarComRetentativa(fn, maximo = 3) {
  for (let tentativa = 0; tentativa < maximo; tentativa++) {
    try {
      return await fn()
    } catch (erro) {
      if (tentativa === maximo - 1 || !erroTemporario(erro)) throw erro
      await esperar(1000 * 2 ** tentativa)
    }
  }
}

def somar_tamanhos(no):
    # caso base: arquivo nao tem filhos
    if no["tipo"] == "arquivo":
        return no["tamanho"]
    # caso recursivo: a pasta e a soma do que ha dentro
    return sum(somar_tamanhos(filho) for filho in no["filhos"])

